def min_moves_to_equalize_strings(n, A, B):
    if A == B:
        return 0

    # Create a list to store the positions of each character in A
    positions = {char: [] for char in 'abcdefghijklmnopqrst'}
    for i, char in enumerate(A):
        positions[char].append(i)

    moves = 0
    for i in range(n):
        if A[i] != B[i]:
            # Find the target character to replace A[i] with
            target_char = None
