                    target_char = char
                    break

            if target_char is None:
                # No valid character to replace, return -1
                return -1

            # Replace all occurrences of A[i] with target_char
            for pos in positions[A[i]]:
                A = A[:pos] + target_char + A[pos+1:]

            # Reset the positions list after each move
            positions = {char: [] for char in 'abcdefghijklmnopqrst'}
            for i, char in enumerate(A):
                positions[char].append(i)

            moves += 1

            # Check if strings are equal now
            if A == B:
                return moves

    return -1

